                self.updateMousePosition( event );
                var end = {
                    x:self.lastMousePoint.x,
                    y: self.lastMousePoint.y
                };
                var distance = parseInt( Tx.Math.distanceBetween2Points( start, end ) );
                var angle = Tx.Math.angleBetween2Points( start, end );

